    #[test]
    fn inherited_generic_fields_instantiate_calls_constructs_and_indexes() {
        let source="interface Base<T> {base:T;(v:T):T;new(v:T):{v:T};[key:string]:T} interface Mid<U> extends Base<U> {mid:U;[key:string]:U} interface Leaf extends Mid<number> {leaf:number}";
        let arena=tsr_core::Arena::new();
        let parsed=tsr_parser::parse(&arena,source);
        assert!(parsed.diagnostics.is_empty());
        let bound=tsr_binder::bind(&arena,parsed.source_file,&parsed.nodes,tsr_binder::FileInfo {name:"test.ts",text:source});
        let root=parsed.source_file.node_id().unwrap();
        let mut checker=crate::Checker::new(&bound,&parsed.nodes,&parsed.node_map);
        let owner=checker.binder.lookup_local(root,"Leaf").unwrap();
        let ty=checker.get_declared_type_of_symbol(owner);
        let key=ImageKey {ty,receiver:ty};
        assert!(checker.publication_image(key));
        let image=&checker.member_publication.images[&key];
        let mut names:Vec<_>=image.members.keys().cloned().collect();names.sort();
        assert_eq!(names,["base","leaf","mid"]);
        assert!(image.done && image.published && image.frames.is_empty());
        let (calls,constructs,indexes)=(image.calls.clone(),image.constructs.clone(),image.indexes.clone());
        assert_eq!((calls.len(),constructs.len(),indexes.len()),(1,1,1));
