        let key=ImageKey {ty,receiver:ty};
        assert!(checker.publication_image(key));
        let image=&checker.member_publication.images[&key];
        let mut names:Vec<_>=image.members.keys().cloned().collect();names.sort();
        assert_eq!(names,["base","leaf","mid"]);
        assert!(image.done && image.published && image.frames.is_empty());
        let (calls,constructs,indexes)=(image.calls.clone(),image.constructs.clone(),image.indexes.clone());
        assert_eq!((calls.len(),constructs.len(),indexes.len()),(1,1,1));
        assert_eq!(checker.parameter_type(&calls[0].parameters[0]),checker.intrinsics.number);
