    #[test]
    fn published_member_natural_partial_prefix_continues() {
        with_checker("interface Root {root:number} interface Later {later:boolean} interface A<T> extends Root,B<T>,Later {a:T} interface B<T> extends A<T> {b:T} declare const receiver:A<number>; const probe=receiver.root;",|checker,root| {
            checker.apply_compiler_options(&tsr_core::CompilerOptions {strict:tsr_core::Tristate::False,target:tsr_core::ScriptTarget::ES2020,..tsr_core::CompilerOptions::default()});
            let a=checker.binder.lookup_local(root,"A").unwrap();
            let ty=checker.get_declared_type_of_symbol(a);
            let _=publication(checker,ty,"a");
            let observations=checker.member_publication.base_reentries.clone();
            let active_a:Vec<_>=observations.iter().filter(|(owner,_,_)| *owner==a).collect();
            let names:Vec<_>=active_a.iter().map(|(_,types,done)| (types.iter().map(|&t|checker.type_to_string(t)).collect::<Vec<_>>(),*done)).collect();
            println!("NATURAL_PARTIAL observations={names:?}");
