                let view = checker.symbols.view(&first).unwrap();
                let private = view.flags().contains(tsr_binder::SymbolFlags::TRANSIENT);
                assert!(!view.check_flags().contains(crate::symbol_access::CheckFlags::INSTANTIATED), "composite clone is not an instantiation");
                println!("PUBLISHED_SCALAR order={order} private={private} symbol={first:?}");
                observed.push(private);
                for _ in 0..3 {
                    assert_eq!(publication(checker, receiver, "value"), first, "warm lookup must retain actual published handle");
                }
            });
        }
        assert_eq!(observed, [false,true,false], "native Single/Merged/Single history");
    }
    #[test]
    fn published_member_scalar_modifiers_preserve_query_history() {
        use crate::symbol_access::CheckFlags;
        for (modifier,classes) in [("readonly ",false),("private ",true)] {
            let source=if classes {
                format!("class Base<T> {{ {modifier}value!:number }} class Left<U> extends Base<U> {{ declare left:U }} class Right<V> extends Base<V> {{ declare right:V }} type Both=Left<string>&Right<number>; declare const receiver:Both; const probe=receiver.value;")
            } else {
                format!("interface Base<T> {{ {modifier}value:number }} interface Left<U> extends Base<U> {{ left:U }} interface Right<V> extends Base<V> {{ right:V }} type Both=Left<string>&Right<number>; declare const receiver:Both; const probe=receiver.value;")
            };
            let mut private=Vec::new();
            for order in 0..3 {
                with_checker(&source,|checker,root| {
                    if order==2 { checker.check_source_file(root,crate::check::FileContext {ambient:false,has_parse_errors:false}); }
                    let bound=checker.binder.lookup_local(root,"receiver").unwrap();
                    let receiver=checker.get_type_of_symbol(bound);
                    if order==1 { let probe=checker.binder.lookup_local(root,"probe").unwrap();checker.get_type_of_symbol(probe); }
                    let symbol=publication(checker,receiver,"value");
                    let is_private=checker.symbols.view(&symbol).unwrap().flags().contains(tsr_binder::SymbolFlags::TRANSIENT);
                    private.push(is_private);
                    assert!(!checker.symbols.view(&symbol).unwrap().check_flags().contains(CheckFlags::INSTANTIATED));
                    assert_eq!(checker.publication_read(&symbol),checker.intrinsics.number);
                    for _ in 0..3 { assert_eq!(publication(checker,receiver,"value"),symbol); }
                    println!("PUBLISHED_SCALAR_MODIFIER modifier={modifier:?} order={order} private={is_private}");
                });
            }
            assert_eq!(private,[false,true,false],"native modifier history {modifier}");
        }
    }


