pub(crate) fn suggested_lib_for(name: &str) -> Option<&'static str> {
    LIB_FEATURE_NAMES
        .binary_search_by_key(&name, |(feature, _)| *feature)
        .ok()
        .map(|index| LIB_FEATURE_NAMES[index].1)
}

