import hashlib,json,subprocess,shutil,tarfile
from pathlib import Path
root=Path(Path('/tmp/tsr-this-admission-path').read_text().strip())
source=root/'source';setup=json.loads((root/'setup.json').read_text())
entry=json.loads((root/'entry-candidate-sources.json').read_text())
owned=list(entry);final={p:(source/p).read_text() for p in owned}
(root/'final-candidate-sources.json').write_text(json.dumps(final,indent=2)+'\n')
sha=lambda b:hashlib.sha256(b).hexdigest()
records=[]
assert json.loads((root/'admission-green-library.json').read_text())['returncode']==0
try:
    for mode in ('candidate','entry','baseline'):
        if mode=='entry':
            for p,text in entry.items():(source/p).write_text(text)
        if mode=='baseline':
            with tarfile.open(root/'baseline.tar') as archive:
                for p in owned:
                    try:(source/p).write_bytes(archive.extractfile(p).read())
                    except KeyError:(source/p).unlink()
        label=mode+'-binaries'
        command=['rtk','proxy','python3','/tmp/tsr-this-admission-run.py',label,'rtk','proxy','cargo','build','--release','-p','tsr','-p','tsr-conformance','--bin','tsr','--example','verdictdump','--example','diagverdictdump']
        p=subprocess.run(command,capture_output=True,text=True,timeout=600)
        print(p.stdout[-800:]+p.stderr[-500:],flush=True)
        run=json.loads((root/(label+'.json')).read_text());assert run['returncode']==0
        outputs={}
        for binary,path in {'tsr':'release/tsr','verdictdump':'release/examples/verdictdump','diagverdictdump':'release/examples/diagverdictdump'}.items():
            dest=root/(mode+'-'+binary);shutil.copy2(source/'target'/path,dest)
            outputs[binary]={'path':str(dest),'sha256':sha(dest.read_bytes())}
        records.append({'mode':mode,'source_hashes':run['source_hashes_after'],'outputs':outputs})
finally:
    for p,text in final.items():(source/p).write_text(text)
    assert all((source/p).read_text()==text for p,text in final.items())
    (root/'binary-triple.json').write_text(json.dumps({'source_revision':setup['source_revision'],'native_revision':setup['native_revision'],'fixture_revision':setup['fixture_revision'],'builds':records,'candidate_restored':True,'baseline_reused':False},indent=2)+'\n')
print(json.dumps({'build_modes':[r['mode'] for r in records],'candidate_restored':True}))

