    paths[2].write_text(paths[2].read_text()+'''
func TestNativeThisArgumentAdmissionParsedProgram(t *testing.T) {
 body:="interface Plain {value:number} interface DerivedPlain extends Plain {own:boolean} interface Self {self:this} interface Generic<T> {value:T} declare class Box {value:number} declare const plain:Plain; declare const derived:DerivedPlain; declare const selfValue:Self; declare const generic:Generic<number>; declare const box:Box; declare const whole:Plain & Self;"
 for _,name:=range []string{"plain","derived","selfValue","generic","box"} {for _,order:=range []string{"cold","checked-first","warm"} {t.Run(name+"/"+order,func(t *testing.T) {
 config:=`{"compilerOptions":{"strict":true,"target":"es2020","types":[],"skipLibCheck":true,"noEmit":true,"incremental":false,"composite":false,"singleThreaded":true},"files":["input.ts"]}`
