 p:=compiler.NewProgram(compiler.ProgramOptions{Config:parsed,Host:host});p.BindSourceFiles()
 file:=p.GetSourceFile("/input.ts")
 if order=="checked-first" {p.GetSemanticDiagnostics(t.Context(),file)}
 c,done:=p.GetTypeChecker(t.Context());defer done()
 variables:=map[string]*ast.Node{}
