 if variables[name]==nil || variables["whole"]==nil {t.Fatal("missing variables")}
 ty,receiver:=c.GetTypeAtLocation(variables[name]),c.GetTypeAtLocation(variables["whole"])
 if order=="warm" {c.NativeThisArgumentAdmission(ty,receiver)}
 row:=c.NativeThisArgumentAdmission(ty,receiver);row["name"]=name;row["order"]=order
 encoded,_:=json.Marshal(row);t.Logf("NATIVE_THIS_ADMISSION %s",encoded)
 changes:=name!="plain" && name!="derived"
 if row["reference"]!=changes || row["same_identity"]==changes || row["repeat_same_identity"]!=true {t.Fatal(row)}
 if changes && row["final_argument_is_receiver"]!=true {t.Fatal(row)}
 })}}
